export function findCodeMoney(mezzo, soldi, orange) {
  const numbers = [Number(mezzo), Number(soldi), Number(orange)];

  if (numbers.some((number) => Number.isNaN(number))) {
    return null;
  }

  const code = numbers.join("-");

  const result = codexMatrixMoney[code];

  if (!result) {
    console.log("Codice karmico non trovato:", code);
    return null;
  }

  return {
    text: result.text,
    numbers,
    code,
  };
}
